const inp = $input.first().json || {};
const LAYOUTS = { L0_NONE: [], L1_C: [['C']], L2_C: [['C'],['C']], L2_CU: [['C'],['U']], L3_C: [['C'],['C'],['C']], L3_CCU: [['C'],['C'],['U']], L4_CCCC: [['C'],['C'],['C'],['C']], L4_CCUC: [['C'],['C'],['U'],['C']], L5_CCCUC: [['C'],['C'],['C'],['U'],['C']], L6_C: [['C'],['C'],['C'],['C'],['C'],['C']], L7_C: [['C'],['C'],['C'],['C'],['C'],['C'],['C']], L8_C: [['C'],['C'],['C'],['C'],['C'],['C'],['C'],['C']], LAYOUT_MENU: [['C'],['C'],['C'],['C'],['U','C']], LAYOUT_BMODEL: [['C','C'],['C'],['C','C'],['C','C'],['C']] };
// Telegram callback_data limit is 1-64 BYTES (UTF-8), not JS string length.
function byteLen(s) { try { return new TextEncoder().encode(s).length; } catch (e) { return encodeURIComponent(s).replace(/%[0-9A-F]{2}/gi, 'x').length; } }
const corr = String(inp.correlation_id == null ? '' : inp.correlation_id).slice(0, 100);
function fail(code) { return [{ json: { valid: false, error_code: code, chat_id: String(inp.chat_id == null ? '' : inp.chat_id), correlation_id: corr, layout: '' } }]; }
const chatId = String(inp.chat_id == null ? '' : inp.chat_id).trim();
if (!/^-?[0-9]{1,20}$/.test(chatId)) return fail('INVALID_CHAT_ID');
const text = String(inp.text == null ? '' : inp.text);
if (text.trim() === '') return fail('EMPTY_TEXT');
if (text.length > 4096) return fail('TEXT_TOO_LONG');
const layout = String(inp.keyboard_layout_id == null ? '' : inp.keyboard_layout_id).trim();
if (!Object.prototype.hasOwnProperty.call(LAYOUTS, layout)) return fail('UNKNOWN_LAYOUT');
const spec = LAYOUTS[layout];
const raw = inp.keyboard_data;
const rows = Array.isArray(raw) ? raw : (raw && Array.isArray(raw.rows) ? raw.rows : []);
if (rows.length !== spec.length) return fail('KEYBOARD_SHAPE_MISMATCH');
const kb = [];
for (let r = 0; r < spec.length; r++) {
  const specRow = spec[r];
  const inRow = rows[r];
  if (!Array.isArray(inRow) || inRow.length !== specRow.length) return fail('KEYBOARD_SHAPE_MISMATCH');
  const outRow = [];
  for (let b = 0; b < specRow.length; b++) {
    const src = inRow[b] || {};
    const btnText = String(src.text == null ? '' : src.text).trim();
    if (btnText === '') return fail('EMPTY_BUTTON_TEXT');
    if (btnText.length > 128) return fail('BUTTON_TEXT_TOO_LONG');
    if (specRow[b] === 'C') {
      const cb = String(src.callback_data == null ? '' : src.callback_data).trim();
      if (cb === '') return fail('EMPTY_CALLBACK_DATA');
      if (byteLen(cb) > 64) return fail('CALLBACK_DATA_TOO_LONG');
      outRow.push({ text: btnText, callback_data: cb });
    } else {
      const url = String(src.url == null ? '' : src.url).trim();
      if (!/^https?:\/\/[^\s]{3,}$/i.test(url)) return fail('INVALID_BUTTON_URL');
      outRow.push({ text: btnText, url: url });
    }
  }
  kb.push(outRow);
}
return [{ json: { valid: true, error_code: '', chat_id: chatId, text: text, layout: layout, kb: kb, disable_preview: inp.disable_preview === true, correlation_id: corr } }];

const v = $('Validate Transport Payload').first().json || {};
const r = $input.first().json || {};
const errRaw = r.error;
const msg = String((errRaw && (errRaw.message || errRaw.description)) || r.description || (typeof errRaw === 'string' ? errRaw : '') || '');
const okFlag = r.ok === true || (r.result && r.result.message_id !== undefined) || r.message_id !== undefined;
if (okFlag && !errRaw) {
  return [{ json: { ok: true, chat_id: String(v.chat_id == null ? '' : v.chat_id), message_id: String((r.result && r.result.message_id) || r.message_id || ''), correlation_id: String(v.correlation_id == null ? '' : v.correlation_id), error_code: '', retryable: false } }];
}
const m = msg.toLowerCase();
let code = 'TELEGRAM_SEND_FAILED';
let retry = true;
if (m.indexOf('bot was blocked') >= 0 || m.indexOf('user is deactivated') >= 0 || m.indexOf('chat not found') >= 0 || m.indexOf('forbidden') >= 0) { code = 'CHAT_UNAVAILABLE'; retry = false; }
else if (m.indexOf('button_url_invalid') >= 0 || m.indexOf('button_data_invalid') >= 0 || m.indexOf('parse entities') >= 0 || m.indexOf('message is too long') >= 0 || m.indexOf('bad request') >= 0) { code = 'INVALID_MESSAGE'; retry = false; }
else if (m.indexOf('too many requests') >= 0 || m.indexOf('429') >= 0) { code = 'RATE_LIMITED'; retry = true; }
else if (m.indexOf('timeout') >= 0 || m.indexOf('etimedout') >= 0 || m.indexOf('econnreset') >= 0 || m.indexOf('502') >= 0 || m.indexOf('503') >= 0 || m.indexOf('504') >= 0) { code = 'TELEGRAM_UNAVAILABLE'; retry = true; }
return [{ json: { ok: false, chat_id: String(v.chat_id == null ? '' : v.chat_id), message_id: '', correlation_id: String(v.correlation_id == null ? '' : v.correlation_id), error_code: code, retryable: retry } }];

